const $=id=>document.getElementById(id);
let s; const req=n=>n===1?[1,0]:[0,n===3?1:0];
function log(t){s.logs.unshift(`${Math.floor(s.time/60).toString().padStart(2,'0')}:${Math.floor(s.time%60).toString().padStart(2,'0')}  ${t}`);s.logs=s.logs.slice(0,40)}
function tell(t){s.note=t;log(t);render()}
function reset(){s={time:0,score:0,goal:2,serial:1,w:[0,0],r:null,train:{n:1,loc:'A'},logs:[],note:'第1列車が西方で待機中。2番線への入場進路を設定してください。',pause:false,speed:1};log('装置起動・全信号停止');render()}
function occupied(b){return s.train?.loc===b}
function switchLocked(){return occupied('T')||!!(s.r&&!s.r.throatReleased)}
function setRoute(){if(s.r)return tell('進路競合：先行進路が解錠されていません。');let n=+$('dest').value,d=$('dir').value;if(occupied('T'))return tell('てっ査鎖錠：T在線中です。');if(d==='in'&&occupied('P'+n))return tell('進路照査不成立：着点番線が在線中です。');if(d==='out'&&(!occupied('P'+n)||occupied('A')))return tell('進路照査不成立：出発列車または西方の空きを確認してください。');s.w=req(n);s.r={n,d,green:true,approach:d==='out'||occupied('A'),stage:-1,timer:0,throatReleased:false,cancel:null};tell(`${d==='in'?'入場':'出発'}進路 ${n}番線を鎖錠。信号：進行。`)}
function cancel(){let r=s.r;if(!r)return tell('取消す進路はありません。');r.green=false;if(r.stage>=0)return tell('信号停止。列車進入済みのため、通過完了まで進路鎖錠を保持。');if(r.cancel!==null)return tell('接近鎖錠の解錠時分を計時中です。');if(r.approach){r.cancel=20;tell('信号停止。接近鎖錠：20秒の時素解錠を開始。')}else{s.r=null;tell('信号停止。接近列車なし：進路解錠。')}}
function toggle(i){if(switchLocked())return tell(`W${i+1}転換不可：${occupied('T')?'軌道回路':'進路・側面防護'}鎖錠中。`);s.w[i]=1-s.w[i];tell(`W${i+1}を${s.w[i]?'反位':'定位'}へ転換。`)}
function spawn(){if(s.train)return tell('現在の列車を西方へ出発させてください。');s.train={n:++s.serial,loc:'A'};if(s.r?.d==='in'&&s.r.green)s.r.approach=true;tell(`第${s.serial}列車が西方接近区間に到着。指定は${s.goal}番線。`)}
function tick(dt){if(s.pause)return;s.time+=dt;let r=s.r;if(!r)return render();if(r.cancel!==null){r.cancel=Math.max(0,r.cancel-dt);if(r.cancel===0){s.r=null;log('時素満了。接近鎖錠・進路鎖錠を解錠。')}return render()}let origin=r.d==='in'?'A':'P'+r.n;if(r.stage===-1&&r.green&&occupied(origin)){r.approach=true;r.timer+=dt;if(r.timer>=2){r.stage=0;r.timer=0;r.green=false;s.train.loc='T';log('列車がTに進入。信号自動復位、進路鎖錠を継続。')}}else if(r.stage===0){r.timer+=dt;if(r.timer>=5){s.train.loc=r.d==='in'?'P'+r.n:'A';r.stage=1;r.timer=0;r.throatReleased=true;log('列車後尾がTを通過。転てつ器区分を解錠。')}}else if(r.stage===1){r.timer+=dt;if(r.timer>=4){if(r.d==='in'){if(r.n===s.goal){s.score++;s.goal=[2,1,3][s.score%3];s.note='指定番線への到着成功！ 同じ番線から西方へ出発させましょう。'}else s.note='指定外の番線に到着。出発させて次の列車で挑戦しましょう。';log('到着確認。進路全体を解錠。')}else{s.train=null;s.note='出発完了。「西方に列車を呼ぶ」で次の列車へ。';log('列車が西方へ退出。進路全体を解錠。')}s.r=null}}render()}
function render(){let r=s.r;$('mission').textContent=`第${s.serial+(s.train?0:1)}列車を ${s.goal}番線へ誘導`;$('score').textContent=s.score;$('clock').textContent=`${Math.floor(s.time/60).toString().padStart(2,'0')}:${Math.floor(s.time%60).toString().padStart(2,'0')}`;$('notice').textContent=s.note;$('log').textContent=s.logs.join('\n');$('log').style.whiteSpace='pre-wrap';$('sig').setAttribute('fill',r?.green?'#8dff9b':'#ff655d');for(let b of ['A','T','P1','P2','P3'])$('b'+b).setAttribute('class','rail'+(occupied(b)?' occupied':r&&(b==='T'&&!r.throatReleased||b==='P'+r.n||b==='A'&&r.d==='out')?' route':''));for(let n=1;n<=3;n++)$('p'+n).setAttribute('class','rail'+(occupied('T')&&r?.n===n?' occupied':r?.n===n&&!r.throatReleased?' route':''));s.w.forEach((v,i)=>{$('w'+(i+1)).textContent=`W${i+1}：${v?'反位':'定位'} ${switchLocked()?'🔒':''}`;$('sw'+(i+1)).textContent=`W${i+1} ${v?'反位':'定位'}${switchLocked()?' [鎖錠]':''}`});$('locks').innerHTML=`進路鎖錠：<b>${r?`${r.d==='in'?'入場':'出発'} ${r.n}番線・鎖錠中`:'解錠'}</b><br>関係する転てつ器：${switchLocked()?'W1・W2 鎖錠中':'解錠'}<br>接近鎖錠：${r?.cancel!==null&&r?.cancel!==undefined?'解錠まで '+Math.ceil(r.cancel)+' 秒':r?.approach?'成立':'なし'}<br>てっ査鎖錠：${occupied('T')?'T在線・成立':'T空き'}<br>区分解錠：${r?.throatReleased?'T区分 解錠済み':r?'列車後尾の通過待ち':'未設定'}<br>競合進路：${r?'共通のど部を使う全進路を抑止':'設定可'}`;$('pause').textContent=s.pause?'再開':'一時停止';$('speed').textContent='速度 ×'+s.speed;let t=s.train;let x=t?.loc==='A'?120:t?.loc==='T'?320:800,y=t?.loc==='P1'?90:t?.loc==='P3'?290:190;$('trains').innerHTML=t?`<rect x="${x-30}" y="${y-13}" width="60" height="26" rx="5" fill="#f3b278"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="#202c23" font-size="13" font-weight="bold">${t.n}列車</text>`:''}
$('set').onclick=setRoute;$('cancel').onclick=cancel;$('w1').onclick=()=>toggle(0);$('w2').onclick=()=>toggle(1);$('spawn').onclick=spawn;$('pause').onclick=()=>{s.pause=!s.pause;render()};$('speed').onclick=()=>{s.speed=s.speed===1?3:1;render()};$('reset').onclick=()=>{if(confirm('運転記録と得点をリセットしますか？'))reset()};reset();setInterval(()=>{if(!document.hidden)tick(.1*s.speed)},100);
